/**
 * Main-thread facade over the SharedWorker data hub. Panels and the
 * workspace shell depend ONLY on this interface (never on SharedWorker/
 * MessagePort directly), so they can be built against a stable contract
 * while the concrete implementation (createDataHubClient, in
 * createDataHubClient.ts) is developed independently.
 *
 * Every subscribe* method returns an unsubscribe function. Multiple panels
 * subscribing to the same symbol/stream must be deduplicated upstream in
 * the hub (ref-counted) - callers do not need to worry about that here.
 */
import type { ConnectionStatus } from './protocol';
import type {
  OrderBookSnapshotView,
  TradeTapeEntry,
  Candle,
  WatchlistRow,
  KlineInterval,
  Symbol,
} from '../types';

export interface DataHubClient {
  readonly clientId: string;

  subscribeOrderBook(symbol: Symbol, onUpdate: (book: OrderBookSnapshotView) => void): () => void;
  subscribeTrades(symbol: Symbol, onUpdate: (trades: TradeTapeEntry[]) => void): () => void;
  subscribeCandles(
    symbol: Symbol,
    interval: KlineInterval,
    onUpdate: (candle: Candle) => void,
  ): () => void;
  /** Single shared `!miniTicker@arr` stream, filtered/sorted client-side. */
  subscribeWatchlist(onUpdate: (rows: WatchlistRow[]) => void): () => void;

  onConnectionStatus(cb: (status: ConnectionStatus) => void): () => void;
  getConnectionStatus(): ConnectionStatus;

  /** Switches the hub into (or out of) replay mode, feeding recorded samples instead of live Binance data. */
  setReplayMode(enabled: boolean, speed?: number): void;
  /** Stress-testing hooks surfaced in the UI; no-ops when not in replay mode. */
  injectFault(kind: 'dropConnection' | 'gap', symbol?: Symbol): void;

  dispose(): void;
}

import React, { createContext, useContext } from 'react';
import type { DataHubClient } from '../core/hub/DataHubClient';

const DataHubReactContext = createContext<DataHubClient | null>(null);

export function DataHubProvider({
  client,
  children,
}: {
  client: DataHubClient;
  children: React.ReactNode;
}) {
  return <DataHubReactContext.Provider value={client}>{children}</DataHubReactContext.Provider>;
}

/** Every panel/workspace component reads the hub through this hook - never constructs its own SharedWorker connection. */
export function useDataHub(): DataHubClient {
  const client = useContext(DataHubReactContext);
  if (!client) {
    throw new Error('useDataHub() called outside a <DataHubProvider>');
  }
  return client;
}

/**
 * Cross-window symbol linking. Panels that share a `linkGroup` id change
 * symbol together, including across pop-out windows, via a BroadcastChannel
 * (same-origin, works across windows/tabs without touching the hub).
 */
export interface LinkGroupBus {
  setSymbol(group: string, symbol: string): void;
  subscribe(group: string, cb: (symbol: string) => void): () => void;
  dispose(): void;
}

const CHANNEL_NAME = 'trading-workstation-link-groups';

interface LinkGroupMsg {
  group: string;
  symbol: string;
}

export function createLinkGroupBus(channelName: string = CHANNEL_NAME): LinkGroupBus {
  const channel = new BroadcastChannel(channelName);
  const listeners = new Map<string, Set<(symbol: string) => void>>();

  channel.onmessage = (ev: MessageEvent<LinkGroupMsg>) => {
    const { group, symbol } = ev.data;
    listeners.get(group)?.forEach((cb) => cb(symbol));
  };

  return {
    setSymbol(group, symbol) {
      listeners.get(group)?.forEach((cb) => cb(symbol));
      channel.postMessage({ group, symbol } satisfies LinkGroupMsg);
    },
    subscribe(group, cb) {
      if (!listeners.has(group)) listeners.set(group, new Set());
      listeners.get(group)!.add(cb);
      return () => listeners.get(group)?.delete(cb);
    },
    dispose() {
      channel.close();
      listeners.clear();
    },
  };
}

import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { createLinkGroupBus, type LinkGroupBus } from './linkGroupBus';

const LinkGroupReactContext = createContext<LinkGroupBus | null>(null);

export function LinkGroupProvider({ children }: { children: React.ReactNode }) {
  const bus = useMemo(() => createLinkGroupBus(), []);
  useEffect(() => () => bus.dispose(), [bus]);
  return <LinkGroupReactContext.Provider value={bus}>{children}</LinkGroupReactContext.Provider>;
}

/**
 * For a panel with `linkGroup` (or null for an unlinked panel): returns the
 * current shared symbol for that group plus a setter that broadcasts the
 * change to every other panel (in this window or any pop-out) in the group.
 * When `group` is null, behaves as fully local state.
 */
export function useLinkedSymbol(group: string | null, initialSymbol: string): [string, (symbol: string) => void] {
  const bus = useContext(LinkGroupReactContext);
  const [symbol, setSymbolState] = useState(initialSymbol);

  useEffect(() => {
    if (!group || !bus) return;
    return bus.subscribe(group, setSymbolState);
  }, [group, bus]);

  const setSymbol = (next: string) => {
    setSymbolState(next);
    if (group && bus) bus.setSymbol(group, next);
  };

  return [symbol, setSymbol];
}

