/**
 * Cross-window symbol linking. Panels that share a `linkGroup` id change
 * symbol together, including across pop-out windows, via a BroadcastChannel
 * (same-origin, works across windows/tabs without touching the hub).
 *
 * The bus also remembers each group's current symbol so a panel that joins a
 * group adopts it. Every window's bus hears every change, and the last value
 * is mirrored to localStorage so a window that opened after the change still
 * knows it.
 */
export interface LinkGroupBus {
  setSymbol(group: string, symbol: string): void;
  subscribe(group: string, cb: (symbol: string) => void): () => void;
  /** The group's current symbol, if any window has set or seeded one. */
  getSymbol(group: string): string | null;
  /** Records `symbol` as the group's current symbol only if none is known yet in this window. Does not broadcast. */
  seed(group: string, symbol: string): void;
  dispose(): void;
}

const CHANNEL_NAME = 'trading-workstation-link-groups';
const STORAGE_PREFIX = 'trading-workstation:link-group:';

interface LinkGroupMsg {
  group: string;
  symbol: string;
}

function persist(group: string, symbol: string): void {
  try {
    localStorage.setItem(STORAGE_PREFIX + group, symbol);
  } catch {
    // Storage unavailable - in-memory knowledge still works within this window.
  }
}

function readPersisted(group: string): string | null {
  try {
    return localStorage.getItem(STORAGE_PREFIX + group);
  } catch {
    return null;
  }
}

export function createLinkGroupBus(channelName: string = CHANNEL_NAME): LinkGroupBus {
  const channel = new BroadcastChannel(channelName);
  const listeners = new Map<string, Set<(symbol: string) => void>>();
  const current = new Map<string, string>();

  channel.onmessage = (ev: MessageEvent<LinkGroupMsg>) => {
    const { group, symbol } = ev.data;
    current.set(group, symbol);
    listeners.get(group)?.forEach((cb) => cb(symbol));
  };

  return {
    setSymbol(group, symbol) {
      current.set(group, symbol);
      persist(group, symbol);
      listeners.get(group)?.forEach((cb) => cb(symbol));
      channel.postMessage({ group, symbol } satisfies LinkGroupMsg);
    },
    subscribe(group, cb) {
      if (!listeners.has(group)) listeners.set(group, new Set());
      listeners.get(group)!.add(cb);
      return () => listeners.get(group)?.delete(cb);
    },
    getSymbol(group) {
      return current.get(group) ?? readPersisted(group);
    },
    seed(group, symbol) {
      if (current.has(group)) return;
      current.set(group, symbol);
      persist(group, symbol);
    },
    dispose() {
      channel.close();
      listeners.clear();
    },
  };
}

import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { createLinkGroupBus, type LinkGroupBus } from './linkGroupBus';

const LinkGroupReactContext = createContext<LinkGroupBus | null>(null);

export function LinkGroupProvider({ children }: { children: React.ReactNode }) {
  const bus = useMemo(() => createLinkGroupBus(), []);
  useEffect(() => () => bus.dispose(), [bus]);
  return <LinkGroupReactContext.Provider value={bus}>{children}</LinkGroupReactContext.Provider>;
}

/**
 * For a panel with `linkGroup` (or null for an unlinked panel): returns the
 * current shared symbol for that group plus a setter that broadcasts the
 * change to every other panel (in this window or any pop-out) in the group.
 * When `group` is null, behaves as fully local state.
 *
 * Joining a group (changing `group` after mount) adopts the group's current
 * symbol. On mount the panel keeps its own symbol and only seeds the group if
 * nothing is known yet - a restored layout already stores matching symbols for
 * every member, and must not be overridden by a stale value from an earlier
 * session.
 */
export function useLinkedSymbol(group: string | null, initialSymbol: string): [string, (symbol: string) => void] {
  const bus = useContext(LinkGroupReactContext);
  const [symbol, setSymbolState] = useState(initialSymbol);
  const symbolRef = useRef(symbol);
  symbolRef.current = symbol;
  const mountedGroupRef = useRef(group);

  useEffect(() => {
    if (!group || !bus) {
      mountedGroupRef.current = group;
      return;
    }
    const joined = mountedGroupRef.current !== group;
    mountedGroupRef.current = group;
    const groupSymbol = bus.getSymbol(group);
    if (joined && groupSymbol) {
      setSymbolState(groupSymbol);
    } else {
      bus.seed(group, symbolRef.current);
    }
    return bus.subscribe(group, setSymbolState);
  }, [group, bus]);

  const setSymbol = useCallback(
    (next: string) => {
      setSymbolState(next);
      if (group && bus) bus.setSymbol(group, next);
    },
    [group, bus],
  );

  return [symbol, setSymbol];
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useLinkedSymbol } from '../workspace/LinkGroupContext';
import type { PanelInstanceConfig } from './PanelProps';

export const LINK_GROUPS: ReadonlyArray<{ value: string | null; label: string }> = [
  { value: null, label: 'None' },
  { value: 'A', label: 'Group A' },
  { value: 'B', label: 'Group B' },
  { value: 'C', label: 'Group C' },
  { value: 'D', label: 'Group D' },
];

/**
 * Glue between a panel's `PanelProps` contract and the cross-window
 * link-group bus (`useLinkedSymbol`).
 *
 * `PanelProps` has no dedicated link-group callback, so a link-group change
 * is persisted as `settings.linkGroup`; the workspace promotes it onto
 * `config.linkGroup`.
 *
 * The displayed symbol and `config.symbols[0]` are kept in step both ways:
 * a symbol that arrives through the link group (from another panel or
 * window) is written back via `onSymbolChange` so saved layouts record what
 * the panel actually shows, and an external config change (e.g. a layout
 * reload reusing this panel's id) is adopted and broadcast to the group.
 */
export function usePanelLink(
  config: PanelInstanceConfig,
  onSymbolChange: (symbol: string) => void,
  onSettingsChange: (settings: Record<string, unknown>) => void,
  fallbackSymbol: string,
): {
  symbol: string;
  linkGroup: string | null;
  handleSymbolChange: (symbol: string) => void;
  handleLinkGroupChange: (group: string | null) => void;
} {
  const configSymbol = config.symbols[0] ?? fallbackSymbol;
  const [linkGroup, setLinkGroupState] = useState<string | null>(config.linkGroup);
  const [symbol, setLinkedSymbol] = useLinkedSymbol(linkGroup, configSymbol);

  const symbolRef = useRef(symbol);
  symbolRef.current = symbol;
  const configSymbolRef = useRef(configSymbol);
  configSymbolRef.current = configSymbol;
  const onSymbolChangeRef = useRef(onSymbolChange);
  onSymbolChangeRef.current = onSymbolChange;

  useEffect(() => {
    if (configSymbol !== symbolRef.current) setLinkedSymbol(configSymbol);
    // Only react to the config value itself changing.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [configSymbol]);

  useEffect(() => {
    if (symbol !== configSymbolRef.current) onSymbolChangeRef.current(symbol);
  }, [symbol]);

  useEffect(() => {
    setLinkGroupState(config.linkGroup);
  }, [config.linkGroup]);

  const handleLinkGroupChange = useCallback(
    (next: string | null) => {
      setLinkGroupState(next);
      onSettingsChange({ ...config.settings, linkGroup: next });
    },
    [config.settings, onSettingsChange],
  );

  return { symbol, linkGroup, handleSymbolChange: setLinkedSymbol, handleLinkGroupChange };
}

