      this.broadcastToGateKey(`trades:${symbol}`, [] as TradeTapeEntry[], (trades, seq) => ({ type: 'trades', seq, symbol, trades }));
    }
  }
}

private isReplaySymbol(symbol: Symbol): boolean {
  return this.replayActive && this.replaySymbols.has(symbol);
